@mixin media($value) {

@if $value == pc {
@media(min-width:769px){
@content;
}
}
@if $value == tablet {
@media(max-width:768px) and (min-width: 321px){
@content;
}
}
@if $value == sp {
@media(max-width:320px){
@content;
}
}
}

