// prefix+e で起動するようにキーを割り当てる（プラグインに既定のキーはない）
// プラグインの既定は新規タブで開くので、同じタブの上ペイン（縦 66%）に開くスクリプトを用意する
// ~/.config/herdr/open-ttt.sh を作成
#!/bin/sh
# フォーカス中のペインの Claude Code セッションが worktree で作業中なら、その worktree を開く
export PATH="$HOME/.local/bin:$PATH"

cur=$(herdr pane current)
field() { printf '%s' "$cur" | grep -o "\"$1\":\"[^\"]*\"" | head -1 | cut -d\" -f4; }
dir=$(field cwd)

# Claude Code はセッション中に cd してもペインの cwd が変わらないので、
# セッションログに出てくる worktree パスのうち最後の、まだ存在するものを使う
session=$(field value)
log=$(ls "$HOME"/.claude/projects/*/"$session".jsonl 2>/dev/null | head -1)
if [ -n "$session" ] && [ -n "$log" ]; then
wt=$(grep -oE '/[A-Za-z0-9/._-]*(\.worktrees|/\.claude/worktrees)/[A-Za-z0-9._-]+' "$log" \
| tail -r | while read -r d; do [ -d "$d" ] && echo "$d" && break; done)
[ -n "$wt" ] && dir=$wt
fi

# split は right/down のみなので、下に開いてから上下を入れ替える。resize の amount は比率の増分（0.5 + 0.16）
p=$(herdr plugin pane open --plugin ttt.editor --entrypoint editor --placement split --direction down --focus \
--env "TTT_TARGET_DIR=$dir" | grep -o '"pane_id":"[^"]*"' | head -1 | cut -d\" -f4) &&
herdr pane swap --pane "$p" --direction up &&
herdr pane resize --pane "$p" --direction down --amount 0.16

