// 中断したセッションを後日 resume するとき、一覧にタブ名が出ていると見分けやすい
// ~/.zshrc に追記
# herdr のタブ名を Claude Code / Codex のセッション名にする
# 新規起動（引数なし、または先頭がオプション）のときだけ。サブコマンドや resume 時は何もしない
_herdr_tab_label() {
[[ -n $HERDR_TAB_ID ]] || return 1
local label
label=$(herdr tab get "$HERDR_TAB_ID" 2>/dev/null | jq -r '.result.tab.label // empty')
# 名前を付けていないタブの既定ラベルは数字なので対象外
[[ -n $label && $label != <-> ]] || return 1
print -r -- "$label"
}

claude() {
local label
if [[ -z $1 || $1 == -* ]] &&
(( ! ${@[(I)(-r|--resume|-c|--continue|-p|--print|-n|--name)(|=*)]} )) &&
label=$(_herdr_tab_label); then
command claude --name "$label" "$@"
else
command claude "$@"
fi
}

# Codex には起動時に名前を付けるフラグがないので、入力待ちになったら /rename を送る
_herdr_codex_rename() {
local pane=$1 label=$2 deadline=$((SECONDS + 120))
# herdr が idle と判定するダイアログもあるため、空の入力欄（プレースホルダー）が見えるまで待つ
until [[ $(herdr agent get "$pane" 2>/dev/null | jq -r '.result.agent | "\(.agent) \(.agent_status)"') == "codex idle" ]] &&
herdr pane read "$pane" --source visible | grep -qE '› (Ask Codex to do anything|Ask a follow-up question)'; do
(( SECONDS < deadline )) || return 1
sleep 0.5
done
# 各段階で画面を確かめてから Enter を送る
herdr pane send-text "$pane" /rename &&
herdr pane wait-output "$pane" --source visible --match '› /rename' --timeout 3000 &&
herdr pane send-keys "$pane" enter &&
herdr pane wait-output "$pane" --source visible --match 'Name thread' --timeout 3000 &&
herdr agent prompt "$pane" "$label"
}

codex() {
local label pid rc
if [[ -z $1 || $1 == -* ]] && [[ -n $HERDR_PANE_ID ]] && label=$(_herdr_tab_label); then
_herdr_codex_rename "$HERDR_PANE_ID" "$label" </dev/null &>/dev/null &!
pid=$!
fi
command codex "$@"
rc=$?
# 名前を付ける前に Codex を終えたら待機も止める（次の起動に紛れ込ませない）
[[ -n $pid ]] && kill $pid 2>/dev/null
return $rc
}
